        "title": "Texte nº 1 : Le droit face aux règles de conduite (علاقة القانون بقواعد السلوك البشري)",
        "duration": "45 دقيقة",
        "summary": "الدرس الأول: دراسة علاقة القانون بقواعد السلوك البشري وترجمة أهم المفاهيم.",
        "detailedContent": "[مقدمة]\nLa règle de droit est une règle de conduite sociale. Elle régit les rapports des hommes entre eux dans la société pour y faire régner l'ordre et la justice.\nالقاعدة القانونية هي قاعدة سلوك اجتماعي. إنها تنظم العلاقات بين البشر في المجتمع لفرض النظام والعدالة.\n\n[أولاً: خصائص القاعدة القانونية]\nLa règle de droit présente plusieurs caractéristiques essentielles. Elle est générale, abstraite, obligatoire et sanctionnée par la puissance publique.\nتتميز القاعدة القانونية بعدة خصائص أساسية: فهي عامة، مجردة، ملزمة، ومصحوبة بجزاء تفرضه السلطة العامة.\n- Générale et abstraite: Elle s'applique à tous ceux qui se trouvent dans des conditions identiques.\n- عامة ومجردة: تطبق على الجميع دون تمييز ممن تتوفر فيهم نفس الشروط القانونية.\n- Obligatoire: Elle s'impose à tous les citoyens sous peine de sanction.\n- ملزمة: تفرض نفسها على كافة المواطنين تحت طائلة العقاب القانوني.\n\n[ثانياً: التمييز بين القانون وقواعد السلوك الأخرى]\nLa règle de droit se distingue de la règle morale, de la règle religieuse, ainsi que des règles de bienséance et de courtoisie.\nتختلف القاعدة القانونية عن القاعدة الأخلاقية والدينية، وكذلك عن قواعد اللياقة والمجاملة.\n- Morale: Vise le perfectionnement de l'individu et relève de la conscience.\n- الأخلاق: تستهدف كمال الفرد وترتبط بالضمير الداخلي.\n- Religion: Émane d'une autorité divine et régit les rapports avec Dieu.\n- الدين: يصدر عن سلطة إلهية وينظم العلاقات مع الخالق جل وعلا.\n- Bienséance: Regroupe les règles de politesse (ex: salutations). Leur violation n'entraîne pas de sanction étatique.\n- اللياقة والمجاملة: تشمل قواعد اللياقة والتحية، ومخالفتها لا تؤدي إلى جزاء من الدولة.",
