        "title": "Texte nº 3 : L’Assemblée générale des Nations Unies (الجمعية العامة للأمم المتحدة)",
        "duration": "45 دقيقة",
        "summary": "الدرس الثالث: دراسة الجهاز التداولي لمنظمة الأمم المتحدة واختصاصاته.",
        "detailedContent": "[مقدمة]\nL'Assemblée générale est l'organe principal de délibération, de formulation des politiques et de représentation des Nations Unies.\nالجمعية العامة هي الجهاز الرئيسي للتداول ورسم السياسات والتمثيل في منظمة الأمم المتحدة.\n\n[أولاً: التكوين والتمثيل]\nComposée de tous les 193 États Membres de l'ONU, elle offre un forum multilatéral unique pour débattre de l'ensemble des questions internationales.\nتتكون من جميع الدول الأعضاء الـ 193 في الأمم المتحدة، وتوفر منبراً فريداً متعدد الأطراف لمناقشة كافة القضايا الدولية.\n- Représentation égale: Chaque État membre dispose d'une voix, quelle que soit sa taille ou sa puissance.\n- التمثيل المتساوي: تتمتع كل دولة عضو بصوت واحد، بغض النظر عن حجمها أو قوتها.\n\n[ثانياً: الاختصاصات والقرارات]\nL'Assemblée générale discute de questions relatives au maintien de la paix internationale et de la sécurité, et adopte des résolutions.\nتناقش الجمعية العامة المسائل المتعلقة بحفظ السلم والأمن الدوليين وتعتمد القرارات والتوصيات.\n- Recommandations: Les résolutions de l'Assemblée générale n'ont généralement pas de force juridique contraignante pour les États, mais ont un poids politique important.\n- التوصيات: قرارات الجمعية العامة ليست لها قوة قانونية ملزمة عموماً للدول، لكنها تتمتع بثقل سياسي كبير.\n- Budget: Elle examine et approuve le budget de l'Organisation.\n- الميزانية: تدرس وتصادق على ميزانية المنظمة.",
