        "detailedContent": "[مقدمة]\nLe Conseil de sécurité est l'organe exécutif des Nations Unies chargé du maintien de la paix et de la sécurité internationales.\nمجلس الأمن هو الجهاز التنفيذي للأمم المتحدة المكلف بحفظ السلم والأمن الدوليين.\n\n[أولاً: التشكيل وحق النقض]\nLe Conseil de sécurité est composé de 15 membres, dont 5 permanents et 10 non permanents élus pour deux ans.\nيتكون مجلس الأمن من 15 عضواً، من بينهم 5 أعضاء دائمين و10 أعضاء غير دائمين ينتخبون لمدة سنتين.\n- Membres permanents: La Chine, les États-Unis, la France, le Royaume-Uni et la Russie.\n- الأعضاء الدائمون: الصين، الولايات المتحدة، فرنسا، المملكة المتحدة، وروسيا.\n- Le droit de veto: Le pouvoir des membres permanents de bloquer toute décision majeure par un vote négatif.\n- حق النقض (الفيتو): سلطة الأعضاء الدائمين في منع اتخاذ أي قرار هام بالتصويت السلبي ضده.\n\n[ثانياً: الصلاحيات والقرارات Contraignantes]\nContrairement à l'Assemblée générale, le Conseil de sécurité peut prendre des décisions contraignantes que les États membres sont obligés d'exécuter.\nعلى عكس الجمعية العامة، يمكن لمجلس الأمن اتخاذ قرارات ملزمة يجب على الدول الأعضاء تنفيذها.\n- Résolutions contraignantes: Adoptées sous le Chapitre VII de la Charte des Nations Unies.\n- القرارات الملزمة: تعتمد بموجب الفصل السابع من ميثاق الأمم المتحدة.\n- Sanctions: Il peut imposer des sanctions économiques ou autoriser l'usage de la force militaire.\n- العقوبات: يمكنه فرض عقوبات اقتصادية أو الترخيص باستخدام القوة العسكرية.",
