        "summary": "دراسة مصطلحات القانون الجنائي العام والخاص، والفرق بين شقيه الموضوعي والإجرائي، وتصنيف الجرائم والتعاريف القانونية للجرائم الكبرى.",
        "detailedContent": "[Introduction]\nCriminal Law (or Penal Law) is the branch of law that defines criminal offenses, regulates the apprehension, charging, and trial of suspected persons, and fixes penalties.\nالقانون الجنائي (أو قانون العقوبات) هو فرع القانون الذي يحدد الجرائم الجنائية، وينظم القبض على المشتبه بهم، اتهامهم، ومحاكمتهم، ويقرر العقوبات المقررة.\n\n[First: Substantive vs Procedural Criminal Law]\nCriminal law is divided into two main categories:\n- Substantive Criminal Law: Defines crimes and punishments (e.g. the Penal Code - قانون العقوبات).\n- القواعد الموضوعية: تحدد الجرائم والعقوبات (مثال: قانون العقوبات).\n- Procedural Criminal Law: Governs the investigation, prosecution, and trial (e.g. the Code of Criminal Procedure - قانون الإجراءات الجزائية).\n- القواعد الإجرائية: تنظم التحري، المتابعة، والمحاكمة (مثال: قانون الإجراءات الجزائية).\n\n[Second: Classification of Crimes]\nIn Algeria, crimes are classified according to their gravity into three main classes:\n- Felonies (الجنايات): The most serious crimes, punishable by severe penalties (imprisonment or death).\n- Misdemeanors (الجنح): Medium gravity offenses, punishable by imprisonment (usually between 1 and 5 years) or fines.\n- Infractions / Contraventions (المخالفات): Minor offenses, punishable by short-term detention or small fines.",
