        "duration": "45 دقيقة",
        "summary": "مصطلحات قانون الأسرة الجزائري والزواج والطلاق والولاية والميراث باللغة الإنجليزية.",
        "detailedContent": "[Introduction]\nFamily Law governs personal status, family relationships, marriage, divorce, alimony, guardianship, and inheritance under the Algerian Family Code.\nينظم قانون الأسرة الأحوال الشخصية، العلاقات الأسرية، الزواج، الطلاق، النفقة، الولاية، والميراث بموجب قانون الأسرة الجزائري.\n\n[First: Marriage and Divorce]\n- Marriage (الزواج): A legal and consensual contract concluded between a man and a woman in accordance with legal and religious provisions.\n- الزواج: عقد شرعي ورضائي يبرم بين رجل وامرأة وفقاً للأحكام القانونية والشرعية.\n- Divorce (الطلاق): The legal dissolution of a marriage, which can be initiated by the husband, by mutual consent, or requested by the wife (Khol' or Tatliq).\n- الطلاق: الحل القانوني لرابطة الزوجية، ويمكن أن يبادر به الزوج، أو بالتراضي، أو تطلبه الزوجة (خلع أو تطليق قضائي).\n\n[Second: Guardianship and Succession]\n- Alimony / Maintenance (النفقة): The legal obligation to provide financial support for a spouse and children.\n- النفقة: الالتزام القانوني بتقديم الدعم المالي للزوجة والأولاد.\n- Guardianship (الولاية): The legal authority to manage the affairs and property of a minor.\n- الولاية: السلطة القانونية لإدارة شؤون وأموال القاصر.\n- Inheritance / Succession (الميراث / التركات): The rules governing the transfer of property after death.\n- الميراث / التركات: القواعد التي تنظم انتقال الملكية والتركة بعد الوفاة.",
